    t.mock.timers.tick(1_800_000); const batch = coheadQuestion(h, collectors, mode === "rich"); await publishCoheadEdit(h, batch, mode);
    assert.deepEqual(batch.groups.map(g => g.deadline!.expiresAt), [88_201_000, 88_201_000]);
